    departmentId: "dept-hr",
    departmentNameAr: "\u0642\u0633\u0645 \u0627\u0644\u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0628\u0634\u0631\u064A\u0629",
    status: "active",
